custom_css:
/* header */
.header {
  padding: 0;
}

.header__row {
  border-bottom: 1px solid;
  padding-top: 2.5rem;
  padding-bottom: 1.5rem;
}

/* categories filtering */
.posts__categories-wrapper,
.posts-ajax__categories-wrapper {
  gap: 1rem;
}

.posts-ajax__row {
	justify-content:flex-end;
}

.posts__tab span,
.posts-ajax__tab span {
  display: inline-block;
  font-size: 16px;
  line-height: 1.1;
  border: 1px solid;
  padding: 0.5em 0.75em;
  border-radius: 30px;
}

/* portfolio & blog post grid*/
.post-item {
  border-top: 1px solid;
  border-bottom: 1px solid;
  border-left: 1px solid;
  border-right: 1px solid;
  padding: clamp(1.8rem, 1.8rem + (1vw - 0.48rem) * 2.885, 3rem);
}

.post-item:nth-child(n+2) {
  border-top: none;
}

.lg\:grid-cols-1 .post-item {
  border-top: 1px solid !important;
  border-bottom: 1px solid !important;
  border-left: 1px solid !important;
  border-right: 1px solid !important;
}

.lg\:grid-cols-1 .post-item:nth-child(n+2) {
  border-top: 0 solid !important;
}

@media screen and (min-width: 640px) {
  .sm\:grid-cols-2 .post-item:nth-child(2) {
    border-top: 1px solid;
  }
  .sm\:grid-cols-2 .post-item:nth-child(even) {
    border-left: 0;
  }
  .sm\:grid-cols-2 .post-item:nth-child(n+3) {
    border-top: none;
  }
}
@media screen and (min-width: 1024px) {
  .lg\:grid-cols-2 .post-item:nth-child(n+3) {
    border-top: none;
  }
  .lg\:grid-cols-3 .post-item:nth-child(even) {
    border-left: 1px solid;
  }
  .lg\:grid-cols-3 .post-item:nth-child(3) {
    border-top: 1px solid;
  }
  .lg\:grid-cols-3 .post-item:not(:nth-child(3n+1)) {
    border-left: 0;
  }
}

/* portfolio & blog cards*/

.blog-post-type .post-card-all .post-card__date,
.portfolio-post-type .post-card-all .post-card__date {
  order: 5;
  font-size: 0.875rem;
}
.blog-post-type .post-card-all .post-card__categories,
.portfolio-post-type .post-card-all .post-card__categories {
  order: 1;
  font-size: 0.875rem;
}
.blog-post-type .post-card-all .post-card__image,
.portfolio-post-type .post-card-all .post-card__image {
  order: 2;
}
.blog-post-type .post-card-all .post-card__heading,
.portfolio-post-type .post-card-all .post-card__heading {
  order: 3;
	font-size:20px;
}
.blog-post-type .post-card-all .post-card__excerpt,
.portfolio-post-type .post-card-all .post-card__excerpt {
  order: 4;
  font-size: 0.875rem;
}
.blog-post-type .post-card-all .post-card__button,
.blog-post-type .post-card-all .post-card__author,
.blog-post-type .post-card-all .post-card__tags,
.portfolio-post-type .post-card-all .post-card__button,
.portfolio-post-type .post-card-all .post-card__author,
.portfolio-post-type .post-card-all .post-card__tags {
  display: none;
}
.blog-post-type .post-card-all .post-card__categories,
.portfolio-post-type .post-card-all .post-card__categories {
  width: -moz-fit-content;
  width: fit-content;
  align-self: flex-end;
  padding: 0.5rem 0.75rem;
  border: 1px solid;
  border-radius: 30px;
  line-height: 1.1;
  margin-bottom: 2rem;
}

.blog-post-type .post-card-all .post-card__heading {
  padding-top: 2.5rem;
}

.portfolio-post-type .post-card-all .post-card__date,
.portfolio-post-type .post-card-all .post-card__excerpt {
  display: none;
}
.portfolio-post-type .post-card-all .post-card__heading {
  padding-bottom: 0;
}

/* Blog card zoom hover */
.blog-post-type .post-card .post-card__image img {
  overflow: hidden;
  transform: none;
  margin-left: 0;
  transition: transform 0.2s;
}

.blog-post-type .post-card .post-card__image img {
  transform: none !important;
  margin-left: 0 !important;
}
.blog-post-type .post-card:hover .post-card__image img {
  transform: scale(1.1) !important;
}
.blog-post-type .post-card .post-card__overlay {
  display: none;
}

/* custom thinner separator */
.wp-block-separator {
  border-width: 1px;
}

/* borders for minimalio gallery */
.wp-block-minimalio-blocks-minimalio-gallery.wp-block-gallery.grid.dg__0 {
  gap: 0;
}

.wp-block-minimalio-blocks-minimalio-gallery.grid .wp-block-image {
  border-top: 1px solid;
  border-bottom: 1px solid;
  border-left: 1px solid;
  border-right: 1px solid;
  padding: clamp(1.8rem, 1.8rem + (1vw - 0.48rem) * 2.885, 3rem);
}
.wp-block-minimalio-blocks-minimalio-gallery.grid.grid-cols-1 .wp-block-image:nth-child(n+2) {
  border-top: none;
}
.wp-block-minimalio-blocks-minimalio-gallery.grid.grid-cols-2 .wp-block-image:nth-child(2) {
  border-top: 1px solid;
}
.wp-block-minimalio-blocks-minimalio-gallery.grid.grid-cols-2 .wp-block-image:nth-child(even) {
  border-left: 0;
}
.wp-block-minimalio-blocks-minimalio-gallery.grid.grid-cols-2 .wp-block-image:nth-child(n+3) {
  border-top: none;
}

@media screen and (min-width: 767px) {
  .wp-block-minimalio-blocks-minimalio-gallery.grid.md\:grid-cols-2 .wp-block-image:nth-child(2) {
    border-top: 1px solid;
  }
  .wp-block-minimalio-blocks-minimalio-gallery.grid.md\:grid-cols-2 .wp-block-image:nth-child(even) {
    border-left: 0;
  }
  .wp-block-minimalio-blocks-minimalio-gallery.grid.md\:grid-cols-2 .wp-block-image:nth-child(n+3) {
    border-top: none;
  }
	  .wp-block-minimalio-blocks-minimalio-gallery.grid.md\:grid-cols-3 .wp-block-image:nth-child(even) {
    border-left: 1px solid;
  }
  .wp-block-minimalio-blocks-minimalio-gallery.grid.md\:grid-cols-3 .wp-block-image:nth-child(3),
  .wp-block-minimalio-blocks-minimalio-gallery.grid.md\:grid-cols-3 .wp-block-image:nth-child(2) {
    border-top: 1px solid;
  }
  .wp-block-minimalio-blocks-minimalio-gallery.grid.md\:grid-cols-3 .wp-block-image:not(:nth-child(3n+1)) {
    border-left: 0;
  }
}
@media screen and (min-width: 1024px) {
  .wp-block-minimalio-blocks-minimalio-gallery.grid.lg\:grid-cols-3 .wp-block-image:nth-child(even) {
    border-left: 1px solid;
  }
  .wp-block-minimalio-blocks-minimalio-gallery.grid.lg\:grid-cols-3 .wp-block-image:nth-child(3) {
    border-top: 1px solid;
  }
  .wp-block-minimalio-blocks-minimalio-gallery.grid.lg\:grid-cols-3 .wp-block-image:not(:nth-child(3n+1)) {
    border-left: 0;
  }

}
